{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access block is missing",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The bucket has no account-independent public access block, so a future ACL or bucket policy change could expose its data publicly."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 versioning is disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted objects cannot be recovered from prior versions."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record access requests, reducing the audit evidence available for investigating unauthorized or suspicious activity."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket lacks KMS default encryption",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly use KMS encryption, preventing key-specific access control, rotation, and auditability for stored data."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "Unencrypted transport to S3 is not denied",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "No bucket policy denies requests made without TLS, so clients can potentially transmit data over insecure HTTP connections."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive deletion of bucket contents is enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to delete the bucket even when it contains data, increasing the impact of an accidental or unauthorized destroy operation."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

resource "aws_kms_key" "data" {
  description             = "KMS key for ${local.resource_prefix.value}-data"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = false
  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "data" {
  bucket = aws_s3_bucket.data.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.data.arn,
          "${aws_s3_bucket.data.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "access_logs" {
  bucket        = "${local.resource_prefix.value}-data-access-logs"
  force_destroy = false

  tags = merge({
    Name        = "${local.resource_prefix.value}-data-access-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }\
